"""Exercise every repaired field through the production sanitizer and MathJax."""
import functools,http.server,json,threading,hashlib
from pathlib import Path
from playwright.sync_api import sync_playwright
H=Path(__file__).resolve().parent;R=H.parents[3]
class Quiet(http.server.SimpleHTTPRequestHandler):
 def log_message(self,*args):pass
def main():
 fields=json.loads((H/'fields.json').read_text());fixture=(R/'reference/mathacademy/repairs/2026-10-14-study-backlog/renderer-fixture.html').read_text().replace('<!doctype html>','<!doctype html><html data-theme="light"><link rel="stylesheet" href="/ui/navigation.css">').replace('html{color-scheme:light}body{background:white;color:#171717}.content-card{background:white}','')
 server=http.server.ThreadingHTTPServer(('127.0.0.1',0),functools.partial(Quiet,directory=str(R)));threading.Thread(target=server.serve_forever,daemon=True).start();origin=f'http://127.0.0.1:{server.server_port}';errors=[];reports=[]
 with sync_playwright()as p:
  browser=p.chromium.launch(headless=True);page=browser.new_page(viewport={'width':1100,'height':900});page.on('pageerror',lambda e:errors.append(str(e)));page.route('**/*',lambda route:route.fulfill(body=fixture,content_type='text/html')if route.request.url==origin+'/fixture'else route.continue_()if route.request.url.startswith(origin+'/')else route.abort());page.goto(origin+'/fixture');page.wait_for_function('window.ready===true')
  for offset in range(0,len(fields),20):
   checked=page.evaluate(r'''async rows=>{let out=[];for(let row of rows){let r={entity:row.entity,attribute:row.attribute,before_sha256:row.before_sha256,after_sha256:row.after_sha256};for(let side of ['before','after']){MathJax.typesetClear([content]);const article=document.createElement('article');article.className='lesson-content';let card=document.createElement('div');card.className='content-card';let n=render(row[side],'prose',[]);card.append(n);article.append(card);content.replaceChildren(article);let thrown=null;try{await MathJax.typesetPromise([n])}catch(e){thrown=String(e)}decorateSourceTables(n);const tokens=[];for(let m of MathJax.startup.document.math){if(!n.contains(m.typesetRoot))continue;let t=[];m.root.walkTree(node=>{if(['mi','mn','mo','mtext','ms'].includes(node.kind))t.push(node.getText())});tokens.push(t)}r[side]={tokens,errors:[...n.querySelectorAll('[data-mml-node="merror"],mjx-merror')].map(e=>e.getAttribute('data-mjx-error')||e.textContent),thrown,images:[...n.querySelectorAll('img')].map(e=>e.getAttribute('src')),tables:n.querySelectorAll('.source-table').length,roles:[...n.querySelectorAll('.source-table td,.source-table th')].map(e=>[e.tagName,e.rowSpan,e.colSpan]),badInlineStyles:[...n.querySelectorAll('.source-table[style],.source-table :is(td,th,tr,thead,tbody,tfoot)[style]')].filter(e=>/url\(|position:|display:/.test(e.getAttribute('style'))).length}}r.same_math=JSON.stringify(r.before.tokens)===JSON.stringify(r.after.tokens);r.no_new_errors=r.after.errors.every(e=>r.before.errors.includes(e))&&r.after.thrown===r.before.thrown;r.same_images=JSON.stringify(r.before.images)===JSON.stringify(r.after.images);r.passed=r.no_new_errors&&r.same_images&&r.after.tables>0&&r.after.badInlineStyles===0;delete r.before.tokens;delete r.after.tokens;out.push(r)}return out}''',fields[offset:offset+20]);reports.extend(checked)
   if offset%200==0:print('Player verified',min(offset+20,len(fields)),'/',len(fields),flush=True)
  browser.close()
 server.shutdown();(H/'render-checks.json').write_text(json.dumps(reports,indent=2)+'\n');failed=[r for r in reports if not r['passed']];summary={'fields':len(reports),'passed':not failed and not errors,'failures':failed,'same_rendered_math_fields':sum(r['same_math']for r in reports),'changed_rendered_math_fields':[[r['entity'],r['attribute']]for r in reports if not r['same_math']],'page_errors':errors,'verified_hashes':[[r['entity'],r['attribute'],r['before_sha256'],r['after_sha256']]for r in reports]};(H/'render-verification.json').write_text(json.dumps(summary,indent=2)+'\n');print('Render checks',len(reports),'failures',len(failed),'page errors',errors)
if __name__=='__main__':main()
